 {library==='text'&&<><div className="panel-intro"><h2>Say it in 3D.</h2><p>A good title deserves a little depth.</p></div><Button className="wide primary" onClick={()=>addObject('text')}><Plus/>Add text layer</Button><div className="section-label">FONT COLLECTION <span>{fontList.length}</span></div><div className="font-list">{fontList.map(f=><button key={f.id} className={obj?.font===f.id?'chosen':''} onClick={()=>{if(obj?.type==='text')updateObject({font:f.id});else{const n=makeObject();n.font=f.id;commit({...scene,objects:[...scene.objects,n]});setSelected(n.id)}}}><span style={{fontFamily:`'font-${f.id}',sans-serif`}}>{f.name}</span><small>{f.style}</small></button>)}</div><Button className="wide" onClick={()=>fontInput.current?.click()}><Upload/>Import your font</Button><p className="hint">Static TTF / OTF. Basic Latin layout; script connections and complex shaping vary by font.</p></>}
 {library==='objects'&&<><div className="panel-intro"><h2>A little extra.</h2><p>Real 3D shapes and everyday objects.</p></div><ModelPanel scene={scene} change={commit} select={id=>{setSelected(id);setInspector('object');}} toast={toast}/><label className="search"><Search size={15}/><input aria-label="Search objects" placeholder="Find an object…" value={filter} onChange={e=>setFilter(e.target.value)}/></label><div className="prop-grid">{props.filter(p=>p!=='procedural'&&p.includes(filter.toLowerCase())).map(p=><button key={p} onClick={()=>addObject('prop',p)}><span>{propIcons[p]}</span><small>{names(p)}</small></button>)}</div></>}
